function setupDOB(){const mSel=qs('[name="dobMonth"]');const dSel=qs('[name="dobDay"]');const ySel=qs('[name="dobYear"]');if(!mSel||!dSel||!ySel)return;if(ySel.options.length<=1){const yr=new Date().getFullYear();for(let y=yr-18;y>=yr-100;y--){const opt=document.createElement('option');opt.value=opt.textContent=y;ySel.appendChild(opt)}}
function daysInMonth(m,y){return new Date(y,m,0).getDate()}
function refreshDays(){const m=parseInt(mSel.value||'1',10);const y=parseInt(ySel.value||(new Date().getFullYear()-18),10);const max=daysInMonth(m||1,y||2000);const current=dSel.value;dSel.innerHTML='<option value="" disabled selected>Day</option>';for(let d=1;d<=max;d++){const v=String(d).padStart(2,'0');const opt=document.createElement('option');opt.value=opt.textContent=v;dSel.appendChild(opt)}
if(current&&parseInt(current,10)<=max){dSel.value=String(current).padStart(2,'0')}}
if(dSel.options.length<=1){for(let d=1;d<=31;d++){const v=String(d).padStart(2,'0');const opt=document.createElement('option');opt.value=opt.textContent=v;dSel.appendChild(opt)}}
mSel.addEventListener('change',refreshDays);ySel.addEventListener('change',refreshDays)}
